**销毁（仅 `release()`，无 `stop()`/`reset()`/`dispose()`）**

```166:183:packages/core/core_visual_stream/lib/src/impl/fijk_visual_stream.dart
  Future<void> disconnect() async {
    debugPrint('[VisualStream][Fijk] disconnect');
    final player = _player;
    _player = null;
    await _bufferingSub?.cancel();
    _bufferingSub = null;
    final listener = _playerListener;
    _playerListener = null;
    if (player == null) return;
    if (listener != null) player.removeListener(listener);
    try {
      await player.release();
    } catch (e) {
      debugPrint('[VisualStream][Fijk] release error (ignored): $e');
    }
    _events.add(const VisualStreamEvent.disconnected());
  }
```

